// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the scale factors were successfully computed.
* -   if equal to `i` (a value in the range `[ 1, M ]`), then the row at zero-based index `i-1` is exactly zero.
* -   if equal to `M+j` (a value in the range `[ M+1, M+N ]`), then the column at zero-based index `j-1` is exactly zero.
*/
type StatusCode = number;

/**
* Interface describing `dgeequ`.
*/
interface Routine {
	/**
	* Computes row and column scale factors intended to equilibrate an M-by-N matrix `A` and reduce its condition number.
	*
	* ## Notes
	*
	* -   The row scale factors are stored in `R` (which should have `M` indexed elements) and the column scale factors are stored in `C` (which should have `N` indexed elements).
	* -   The three element output array `out` is populated with `[ ROWCND, COLCND, AMAX ]`, where `ROWCND` is the ratio of the smallest to the largest row scale factor, `COLCND` is the ratio of the smallest to the largest column scale factor, and `AMAX` is the absolute value of the largest element of `A`.
	* -   If the status code is greater than `M`, `R`, `ROWCND`, and `AMAX` contain valid values, but `C` and `COLCND` do not. If the status code is greater than zero and less than or equal to `M`, only `AMAX` contains a valid value. Elements which do not contain valid values are left unmodified.
	*
	* @param order - storage layout of `A`
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param R - output array for the row scale factors
	* @param C - output array for the column scale factors
	* @param out - three element output array whose elements are set to `[ ROWCND, COLCND, AMAX ]`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	* var R = new Float64Array( 2 );
	* var C = new Float64Array( 2 );
	* var out = new Float64Array( 3 );
	*
	* dgeequ( 'row-major', 2, 2, A, 2, R, C, out );
	* // R => <Float64Array>[ 0.5, 0.25 ]
	* // C => <Float64Array>[ ~1.333, 1.0 ]
	* // out => <Float64Array>[ 0.5, 0.75, 4.0 ]
	*/
	( order: Layout, M: number, N: number, A: Float64Array, LDA: number, R: Float64Array, C: Float64Array, out: Float64Array ): StatusCode;

	/**
	* Computes row and column scale factors intended to equilibrate an M-by-N matrix `A` and reduce its condition number using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   The row scale factors are stored in `R` (which should have `M` indexed elements) and the column scale factors are stored in `C` (which should have `N` indexed elements).
	* -   The three element output array `out` is populated with `[ ROWCND, COLCND, AMAX ]`, where `ROWCND` is the ratio of the smallest to the largest row scale factor, `COLCND` is the ratio of the smallest to the largest column scale factor, and `AMAX` is the absolute value of the largest element of `A`.
	* -   If the status code is greater than `M`, `R`, `ROWCND`, and `AMAX` contain valid values, but `C` and `COLCND` do not. If the status code is greater than zero and less than or equal to `M`, only `AMAX` contains a valid value. Elements which do not contain valid values are left unmodified.
	*
	* @param M - number of rows in `A`
	* @param N - number of columns in `A`
	* @param A - input matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param R - output array for the row scale factors
	* @param strideR - stride length for `R`
	* @param offsetR - starting index for `R`
	* @param C - output array for the column scale factors
	* @param strideC - stride length for `C`
	* @param offsetC - starting index for `C`
	* @param out - three element output array whose elements are set to `[ ROWCND, COLCND, AMAX ]`
	* @param strideOut - stride length for `out`
	* @param offsetOut - starting index for `out`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	* var R = new Float64Array( 2 );
	* var C = new Float64Array( 2 );
	* var out = new Float64Array( 3 );
	*
	* dgeequ.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 );
	* // R => <Float64Array>[ 0.5, 0.25 ]
	* // C => <Float64Array>[ ~1.333, 1.0 ]
	* // out => <Float64Array>[ 0.5, 0.75, 4.0 ]
	*/
	ndarray( M: number, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, R: Float64Array, strideR: number, offsetR: number, C: Float64Array, strideC: number, offsetC: number, out: Float64Array, strideOut: number, offsetOut: number ): StatusCode;
}

/**
* Computes row and column scale factors intended to equilibrate an M-by-N matrix `A` and reduce its condition number.
*
* ## Notes
*
* -   The row scale factors are stored in `R` (which should have `M` indexed elements) and the column scale factors are stored in `C` (which should have `N` indexed elements).
* -   The three element output array `out` is populated with `[ ROWCND, COLCND, AMAX ]`, where `ROWCND` is the ratio of the smallest to the largest row scale factor, `COLCND` is the ratio of the smallest to the largest column scale factor, and `AMAX` is the absolute value of the largest element of `A`.
* -   If the status code is greater than `M`, `R`, `ROWCND`, and `AMAX` contain valid values, but `C` and `COLCND` do not. If the status code is greater than zero and less than or equal to `M`, only `AMAX` contains a valid value. Elements which do not contain valid values are left unmodified.
*
* @param order - storage layout of `A`
* @param M - number of rows in `A`
* @param N - number of columns in `A`
* @param A - input matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param R - output array for the row scale factors
* @param C - output array for the column scale factors
* @param out - three element output array whose elements are set to `[ ROWCND, COLCND, AMAX ]`
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var R = new Float64Array( 2 );
* var C = new Float64Array( 2 );
* var out = new Float64Array( 3 );
*
* dgeequ( 'row-major', 2, 2, A, 2, R, C, out );
* // R => <Float64Array>[ 0.5, 0.25 ]
* // C => <Float64Array>[ ~1.333, 1.0 ]
* // out => <Float64Array>[ 0.5, 0.75, 4.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var R = new Float64Array( 2 );
* var C = new Float64Array( 2 );
* var out = new Float64Array( 3 );
*
* dgeequ.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 );
* // R => <Float64Array>[ 0.5, 0.25 ]
* // C => <Float64Array>[ ~1.333, 1.0 ]
* // out => <Float64Array>[ 0.5, 0.75, 4.0 ]
*/
declare var dgeequ: Routine;


// EXPORTS //

export = dgeequ;
